sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    helpers.timing.setTimeout(()=> {
        api.setState("hideStandardTicket",  !event.payload.data);
        if(event.payload.data){
            api.emit("SN_EMBEDX_CASE_VIEW#COMPONENT_READY");
            api.emit('MACROPONENT_TRACK_USAGE_REQUESTED', { 
                event: '[WE] Case View - Component Ready',
                value: {} 
            }); 
        }
    },20);

    var journalAndSpecialFields = [];
    var filterFields = event.payload.data?.GlideViewQuery_Query?.uiView?.glideLayoutItem?._query?.GlideActivity_Query?.getEvents?.filterFields;
    if (filterFields)
        filterFields.forEach(option => {
            if (option.journal || option.specialField) {
                journalAndSpecialFields.push(option);
            }
        });
    api.setState("activityFilterOptions", journalAndSpecialFields);
}
